//! Backend services. Each module ports one Electron service/controller pair
//! and registers its IPC channels under the original names.
//!
//! Porting status per channel: `docs/rust-port-coverage.md` (regenerated by
//! `src-tauri/scripts/prepare-frontend.mjs` on every dev/build run).

pub mod analytics;
pub mod auth;
pub mod discovery;
pub mod friends;
pub mod games;
pub mod settings;
pub mod thumbnails;
pub mod users;
pub mod window;

use crate::ipc::Router;

pub fn register_all(router: &mut Router) {
    window::register(router);
    analytics::register(router);
    settings::register(router);
    auth::register(router);
    friends::register(router);
    users::register(router);
    discovery::register(router);
    games::register(router);
    thumbnails::register(router);
}
